'use client';
import { useEffect, useRef, type RefObject } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useReducedMotion } from '../lib/hooks';
import { Swap, Tip } from '../lib/motion';
import '../designme.css';
import './run-cost.css';

export type RunCostStatus = 'idle' | 'running' | 'stopped' | 'paused' | 'spent';

export interface RunCostRow {
  /** Like "Input tokens" */
  label: string;
  value: number;
}

export interface RunCostProps {
  /** Credits used so far */
  used: number;
  /** The whole budget, like 2000 */
  budget: number;
  /** Where the agent pauses, as a percentage of the budget. Defaults to 90 */
  capAt?: number;
  /** Whether the agent pauses at the cap. Leave it out to let the switch change it */
  capOn?: boolean;
  defaultCapOn?: boolean;
  onCapChange?: (on: boolean) => void;
  /** running is blue, paused (at the cap) amber, spent (the whole budget) red */
  status?: RunCostStatus;
  /** Words in the status tag. Defaults to Idle, Running, Stopped, "Paused at 90%" or "Budget used" */
  statusLabel?: string;
  /** The breakdown under the bar, like input tokens, output tokens and tool calls */
  rows?: RunCostRow[];
  /** Words on the button. Defaults to Start run, Stop, Resume, Raise cap or Start over, by status */
  actionLabel?: string;
  /** Called by the button. What it does is up to you: start, stop, resume, raise the cap */
  onAction?: () => void;
  title?: string;
  /** Draws its own container (the default, as on designme.dev). Set true to sit it flat in a chat thread */
  bare?: boolean;
  className?: string;
}


/** A button as wide as its words: when they change it eases to its new width, keeping no room for a longer word */
function useEaseWidth(ref: RefObject<HTMLElement | null>) {
  const reduce = useReducedMotion();
  useEffect(() => {
    const el = ref.current; if (!el || reduce || typeof ResizeObserver === 'undefined') return;
    let w = 0, busy: Animation | null = null;
    const ro = new ResizeObserver(() => {
      if (busy) return;
      const w1 = el.getBoundingClientRect().width;
      if (w && Math.abs(w1 - w) > .5) {
        busy = el.animate([{ width: w + 'px' }, { width: w1 + 'px' }], { duration: 340, easing: 'cubic-bezier(.23,1,.32,1)' });
        busy.finished.catch(() => {}).then(() => { busy = null; w = el.getBoundingClientRect().width; });
      }
      w = w1;
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref, reduce]);
}

const fmt = (n: number) => Math.round(n).toLocaleString('en-US');
const TONE: Partial<Record<RunCostStatus, string>> = { running: 'dm-b', paused: 'dm-warn', spent: 'dm-bad' };
const ACTION: Record<RunCostStatus, string> = { idle: 'Start run', running: 'Stop', stopped: 'Resume', paused: 'Raise cap', spent: 'Start over' };

/** Credits a run has used against its budget, with a cap the agent pauses at and the tokens behind the number. */
export function RunCost({ used, budget, capAt = 90, capOn, defaultCapOn = true, onCapChange, status = 'idle', statusLabel, rows, actionLabel, onAction, title = 'Credits used', bare = false, className }: RunCostProps) {
  const [cap, setCap] = useControllable(capOn, defaultCapOn, onCapChange);
  const go = useRef<HTMLButtonElement>(null);
  useEaseWidth(go);
  const label = statusLabel ?? { idle: 'Idle', running: 'Running', stopped: 'Stopped', paused: `Paused at ${capAt}%`, spent: 'Budget used' }[status];
  return (
    <div data-dm="" className={cx('dm-rc', !bare && 'dm-panel', className)} style={bare ? { paddingInline: 0 } : undefined}>
      <div className="dm-rc-h">
        <span className="dm-muted">{title}</span>
        <span className={cx('dm-rc-st dm-tag', TONE[status])}><span className="dm-dot" /><Swap className="dm-rc-stt">{label}</Swap></span>
      </div>
      <div className="dm-rc-big"><span className="dm-rc-n dm-num">{fmt(used)}</span><span className="dm-muted"> / {fmt(budget)}</span></div>
      <div className="dm-rc-track" role="meter" aria-label={title} aria-valuemin={0} aria-valuemax={budget} aria-valuenow={Math.round(used)}>
        <div className="dm-rc-fill" style={{ width: Math.max(0, Math.min(100, used / budget * 100)) + '%', background: status === 'paused' ? 'var(--dm-warn-mark)' : 'var(--dm-accent-mark, var(--dm-accent))' }} />
        <Tip label="The agent pauses here"><div className="dm-rc-cap" style={{ left: capAt + '%', opacity: cap ? 1 : 0.2 }} /></Tip>
      </div>
      {rows && (
        <div className="dm-rc-rows">
          {rows.map(r => <div key={r.label}><span>{r.label}</span><span className="dm-num">{fmt(r.value)}</span></div>)}
        </div>
      )}
      <div className="dm-rc-f">
        <label className="dm-rc-cap-t" onClick={e => { e.preventDefault(); setCap(!cap); }}>
          <button type="button" className="dm-toggle" role="switch" aria-checked={cap} aria-label={`Pause at ${capAt} percent`} />
          <span>Pause at {capAt}%</span>
        </label>
        <button ref={go} type="button" className={cx('dm-pill dm-sm dm-rc-go', status === 'running' || status === 'stopped' ? 'dm-line' : 'dm-primary')} onClick={onAction}>
          <Swap>{actionLabel ?? ACTION[status]}</Swap>
        </button>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Run cost ---------- */
/* the card's content sits 16px in from every edge (owner, 18 Nov); nothing in it grows or shrinks when it is pressed */
.dm-rc{padding:var(--dm-s-4)}
.dm-rc :is(.dm-pill,.dm-ib):active{transform:none}
.dm-rc-h{display:flex;align-items:center;justify-content:space-between;font-size:12.5px}
.dm-rc-st{transition:background .3s,color .3s}
/* the status dot is a mark: paused at the cap it takes the bright orange of the bar, while the words keep the darker text orange */
.dm-rc-st.dm-warn .dm-dot{background:var(--dm-warn-mark)}
.dm-rc-big{margin-top:6px;font-size:13px}
.dm-rc-n{font-size:14px;font-weight:500;letter-spacing:-.8px}
/* the track is the neutral rail; the fill is the accent's mark colour, and the warning mark at the cap */
.dm-rc-track{position:relative;height:6px;border-radius:var(--dm-r-xs);background:var(--dm-rail);margin:14px 0 var(--dm-s-4)}
.dm-rc-fill{height:100%;width:0;border-radius:var(--dm-r-xs);background:var(--dm-accent-mark,var(--dm-accent));transition:background .4s}
.dm-rc-cap{position:absolute;left:90%;top:-5px;bottom:-5px;width:2px;border-radius:1px;background:var(--dm-fg2);transition:opacity .3s}
.dm-rc-cap::before{content:"";position:absolute;inset:-6px -8px}
.dm-rc-rows{display:flex;flex-direction:column;gap:2px}
.dm-rc-rows div{display:flex;justify-content:space-between;padding:5px 0;font-size:13px;line-height:18px;color:var(--dm-fg2)}
.dm-rc-rows .dm-num{color:var(--dm-fg)}
.dm-rc-f{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:var(--dm-s-3);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-rc-cap-t{display:flex;align-items:center;gap:9px;font-size:13px;color:var(--dm-fg2);cursor:pointer}
.dm-rc-go{overflow:hidden;justify-content:flex-start}
/* Clean (owner, 17 and 18 Nov): a round card with its hairline, its content 16px in from every edge; the status chip in its
   status colours; a 6px grey rail with the accent fill (the warning mark at the cap) and an ink budget line. The rows are
   plain text (nothing to press, so no hover fill). The foot strip holds the controls 16px from the card's edges and its hairline (owner, 23 Nov): the cap's
   switch is a quiet control whose switch sits on the content's 16px edge, its hover round it, and the button a 28px pill,
   concentric with the card's corner */
:root[data-style="clean"] .dm-rc,:root [data-style="clean"] .dm-rc,:root [data-style="clean"].dm-rc{padding:16px 16px 0}
:root[data-style="clean"] .dm-rc-h,:root [data-style="clean"] .dm-rc-h,:root [data-style="clean"].dm-rc-h{font-size:12.5px}
:root[data-style="clean"] .dm-rc-big .dm-muted,:root [data-style="clean"] .dm-rc-big .dm-muted,:root [data-style="clean"].dm-rc-big .dm-muted{font-size:13px}
:root[data-style="clean"] .dm-rc-track,:root [data-style="clean"] .dm-rc-track,:root [data-style="clean"].dm-rc-track{height:6px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-rail);margin:12px 0 10px}
:root[data-style="clean"] .dm-rc-fill,:root [data-style="clean"] .dm-rc-fill,:root [data-style="clean"].dm-rc-fill{border-radius:var(--dm-r-tiny,3px)}
:root[data-style="clean"] .dm-rc-cap,:root [data-style="clean"] .dm-rc-cap,:root [data-style="clean"].dm-rc-cap{background:var(--dm-fg)}
:root[data-style="clean"] .dm-rc-f,:root [data-style="clean"] .dm-rc-f,:root [data-style="clean"].dm-rc-f{margin:11px -16px 0;padding:var(--dm-strip-y) 16px;border-top:1px solid var(--dm-line);background:var(--dm-strip);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .dm-rc-cap-t,:root [data-style="clean"] .dm-rc-cap-t,:root [data-style="clean"].dm-rc-cap-t{height:28px;padding:0 10px 0 8px;border-radius:var(--dm-r-pill);gap:8px;transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-rc-cap-t:hover,:root [data-style="clean"] .dm-rc-cap-t:hover,:root [data-style="clean"].dm-rc-cap-t:hover{background:var(--dm-row);color:var(--dm-fg)}}
/* (owner, 22 Nov: "foot buttons aligned") the switch itself sits on the content's 16px column, where Credits used starts, its
   hover pill reaching 8px out round it */
:root[data-style="clean"] .dm-rc-cap-t,:root [data-style="clean"] .dm-rc-cap-t,:root [data-style="clean"].dm-rc-cap-t{margin-left:-8px}
/* the running chip is the accent's tint with its words in the accent's text colour: blue in light mode, white in dark (owner,
   22 Nov: Clean dark's accents are white) */
:root[data-style="clean"] .dm-rc-st.dm-b,:root [data-style="clean"] .dm-rc-st.dm-b,:root [data-style="clean"].dm-rc-st.dm-b{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
:root[data-style="clean"] .dm-rc-go,:root [data-style="clean"] .dm-rc-go,:root [data-style="clean"].dm-rc-go{transition:transform var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .dm-rc-cap-t,:root [data-style="clean"] .dm-rc-cap-t,:root [data-style="clean"].dm-rc-cap-t{transition:none}}
